use crate::ffi::put_byte;

const RAND_DEG: usize = 31;
const RAND_SEP: usize = 3;

struct GlibcRandom {
    table: [i32; RAND_DEG],
    fptr: usize,
    rptr: usize,
}

impl GlibcRandom {
    fn new(seed: u32) -> Self {
        // glibc's __srandom_r stores `seed == 0 ? 1 : seed` into state[0],
        // and that SAME guarded value (not the raw seed) is what seeds the
        // Park-Miller recurrence used to fill the rest of the table:
        //   if (seed == 0) seed = 1;
        //   state[0] = seed;
        //   word = seed;             // the guarded value, not the raw one
        //   for (i = 1; i < kc; ++i) { ... ; state[i] = word; }
        // Using the raw (unguarded) seed for `word` only matches for
        // nonzero seeds by coincidence of value, never structurally, and
        // was not actually the source of the mismatch below.
        let guarded_seed: i32 = if seed == 0 { 1 } else { seed as i32 };
        let mut table = [0i32; RAND_DEG];
        table[0] = guarded_seed;
        let mut word: i32 = guarded_seed;
        for i in 1..RAND_DEG {
            let hi: i64 = (word as i64) / 127773;
            let lo: i64 = (word as i64) % 127773;
            let mut w: i64 = (16807i64)
                .wrapping_mul(lo)
                .wrapping_sub((2836i64).wrapping_mul(hi));
            if w < 0 {
                w = w.wrapping_add(2147483647);
            }
            word = w as i32;
            table[i] = word;
        }
        let mut rng = GlibcRandom {
            table,
            fptr: RAND_SEP,
            rptr: 0,
        };
        // glibc's __srandom_r then discards output while warming up:
        //   kc = rand_deg * 10;   // 310
        //   --kc;                 // 309  <- a standalone decrement BEFORE the loop
        //   while (--kc >= 0) random_r(...);
        // A `while (--kc >= 0)` loop starting at kc = N is the
        // pre-decrement-and-test idiom equivalent to `for _ in 0..N`, so it
        // runs exactly N times. Since the standalone `--kc` already dropped
        // kc from rand_deg*10 to rand_deg*10 - 1 before the loop starts,
        // the loop body (one random_r call) runs rand_deg*10 - 1 = 309
        // times in total, not rand_deg*10 = 310. The previous revision
        // used 310, which desynchronized fptr/rptr from glibc's by one
        // extra step for every seed, matching the observed mismatches
        // (including seed=1, where the guarded-vs-raw seed distinction
        // above makes no difference at all).
        for _ in 0..(RAND_DEG * 10 - 1) {
            rng.next_u32();
        }
        rng
    }

    fn next_u32(&mut self) -> u32 {
        let f = self.table[self.fptr] as u32;
        let r = self.table[self.rptr] as u32;
        let val = f.wrapping_add(r);
        self.table[self.fptr] = val as i32;
        let result = (val >> 1) & 0x7fff_ffff;

        self.fptr += 1;
        if self.fptr >= RAND_DEG {
            self.fptr = 0;
        }
        self.rptr += 1;
        if self.rptr >= RAND_DEG {
            self.rptr = 0;
        }

        result
    }

    fn rand(&mut self) -> u32 {
        self.next_u32()
    }
}

pub fn perform_operations(a: u32, b: u32) -> u32 {
    let safe_b: u32 = if b == 0 { 1 } else { b };
    let shift: u32 = b % 32;

    let add = a.wrapping_add(b);
    let sub = a.wrapping_sub(b);
    let mul = a.wrapping_mul(b);
    let div = a / safe_b;
    let shl = a.wrapping_shl(shift);
    let shr = a.wrapping_shr(shift);
    let xor_v = a ^ b;
    let and_v = a & b;
    let or_v = a | b;
    let not_a = !a;

    add ^ sub ^ mul ^ div ^ shl ^ shr ^ xor_v ^ and_v ^ or_v ^ not_a
}

pub fn switch_arith(seed: u32) {
    let mut rng = GlibcRandom::new(seed);
    let a: u32 = rng.rand();
    let b: u32 = rng.rand();

    let result = perform_operations(a, b);
    let choice = result % 10;

    let message: String = match choice {
        0 => format!(
            "Result: {} — The number is as calm as a sleeping sloth.\n",
            result
        ),
        1 => format!(
            "Result: {} — It tried to divide by zero but thought better of it.\n",
            result
        ),
        2 => format!("Result: {} — Secretly wishes it was a float.\n", result),
        3 => format!(
            "Result: {} — Built entirely from left shifts and dreams.\n",
            result
        ),
        4 => format!(
            "Result: {} — Bitwise ANDed its way into your heart.\n",
            result
        ),
        5 => format!("Result: {} — XOR marks the spot.\n", result),
        6 => format!(
            "Result: {} — Practically a math meme at this point.\n",
            result
        ),
        7 => format!(
            "Result: {} — Stronger than a C macro on Monday morning.\n",
            result
        ),
        8 => format!(
            "Result: {} — Thinks it's the boss of all unsigned ints.\n",
            result
        ),
        9 => format!(
            "Result: {} — May contain traces of peanuts and logic gates.\n",
            result
        ),
        _ => format!("Result: {} — How did we even get here?\n", result),
    };

    for byte in message.as_bytes() {
        put_byte(*byte);
    }
}
